bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->symtabs[MACH0_(OBJ_SYM)].nsyms) {
        return false;
    }

    uint32_t desc = bin->symtabs[MACH0_(OBJ_SYM)].descs[idx];
    uint8_t type = (desc >> 8) & 0xFF;

    if (type != N_STUB && type != N_POINTOF) {
        return false;
    }

    uint32_t sym_idx = desc & 0xFFFFFF;

    if (sym_idx >= bin->symtabs[MACH0_(OBJ_SYM)].nsyms) {
        return false;
    }

    if (bin->sym_size == 4) {
        reloc->type = REL_TYPE_IMPORT32;
    } else {
        reloc->type = REL_TYPE_IMPORT64;
    }

    for (size_t i = 0; i < bin->nsecs; i++) {
        struct section_t* sec = &bin->sections[i];
        if (sec->indirectsym == sym_idx) {
            reloc->offset = sec->offset + sec->size;
            reloc->addr = sec->addr + sec->size;
            return true;
        }
    }

    return false;
}

bool parse_import_pointer(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->symbol_count) {
        return false;
    }

    uint8_t* symtab = bin->symtab;
    uint32_t* ind_sym = bin->ind_sym;
    uint64_t offset = 0;
    uint64_t address = 0;
    uint32_t symbol_index = ind_sym[idx];

    if (bin->header->filetype != MachO::MH_DYLIB) {
        return false;
    }

    for (uint32_t i = 0; i < bin->section_count; ++i) {
        struct section_t* sect = &bin->sections[i];
        if (sect->symbol_num == symbol_index) {
            offset = sect->offset;
            address = sect->address;
            break;
        }
    }

    if (!offset || !address) {
        return false;
    }

    reloc->offset = offset;
    reloc->addr = address;
    reloc->type = (bin->header->magic == MachO::MH_MAGIC_64) ? R_X86_64_IMPORT32 : R_X86_64_IMPORT64;
    reloc->sym_idx = symbol_index;
    return true;
}

bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->sym_count) {
        return false;
    }

    uint8_t* sym = bin->sym_table + idx * bin->sym_ent_size;
    uint32_t type = *(uint32_t*)(sym + 2);

    if (bin->word_size == 4) {
        reloc->type = R_MACHO32_32;
    } else {
        reloc->type = R_MACHO64_32;
    }

    for (size_t i = 0; i < bin->section_count; i++) {
        struct section_t* sec = bin->sections[i];
        if (sec->indirect_sym_count > 0) {
            for (size_t j = 0; j < sec->indirect_sym_count; j++) {
                int indirect_idx = *(int*)(sec->indirect_syms + j * 4);
                if (indirect_idx == idx) {
                    reloc->offset = sec->offset + j * 4;
                    reloc->addr = sec->addr + j * 4;
                    return true;
                }
            }
        }
    }

    return false;
}

bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->symtab.nsyms) {
        return false;
    }

    uint8_t desc = (bin->symtab.desc >> (idx * 8)) & 0xFF;
    if (desc == 0) {
        return false;
    }

    reloc->type = (desc & 0x80) ? R_MACHO64_IMPORT32 : R_MACHO64_IMPORT64;

    for (int i = 0; i < bin->symtab.nsyms; i++) {
        if (bin->symtab.indirectsyms[i] == idx + 1) {
            reloc->offset = bin->symtab.pointers[i];
            reloc->addr = bin->symtab.addrs[i];
            return true;
        }
    }

    return false;
}

bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->sym_count) {
        return false;
    }

    uint8_t descriptor = (bin->sym_table)[idx].n_desc;
    uint8_t type = (descriptor >> 4) & 0x0F;

    if (type != N_EXT && type != N_PEXT) {
        return false;
    }

    if (bin->header->magic == MH_CIGAM_64 || bin->header->magic == MH_CIGAM) {
        reloc->type = R_MACHO64;
        reloc->sym_size = sizeof(uint64_t);
    } else {
        reloc->type = R_MACHO32;
        reloc->sym_size = sizeof(uint32_t);
    }

    for (int i = 0; i < bin->sect_count; ++i) {
        struct section_t* sect = &bin->sects[i];
        if (sect->index == idx) {
            reloc->offset = sect->offset;
            reloc->addr = sect->addr;
            return true;
        }
    }

    return false;
}
